    "enableNowPlaying": "Activar Reproduciendo ahora",
    "enableNowPlayingDesc": "Si está activado, la página de inicio muestra un acceso a Stage y se conecta por localhost al servicio now-playing.",
    "nowPlayingFixedConnectionDesc": "Se conecta a ws://localhost:9863/api/ws/lyric. Primero inicia el servicio now-playing en tu equipo.",
