    "lumiereTextOnlyHint": "Solo letra: dibuja únicamente la letra y sus propios efectos (iluminación, brillo, destellos). Se ocultan las fuentes de luz, el humo, las estrellas, el dibujo lineal, el polvo, la letra de fondo, los íconos del tema y el marco. La letra igual se ilumina y se atenúa con los haces (ahora invisibles).",
