    "lumiereSeamlessTransitions": "Transiciones continuas",
    "lumiereSeamlessTransitionsHint": "Transiciones continuas: los cambios de párrafo ocurren dentro de la misma luz, como los cambios de plano dentro de un párrafo (los haces giran al nuevo ángulo, el dibujo lineal se redibuja, la letra vuela a sus nuevos lugares), en lugar de un apagón, un destello o un fundido cruzado. Trazar cada movimiento hace que la letra vuele en cada cambio de línea; Ocultar líneas de trayectoria controla si sus estelas son visibles.",
