        "outcome": "Suéltalo pasado ese punto y se abre la paleta de comandos.",
        "hotspotIntro": "En una pantalla táctil no hay nada sobre lo que pasar el puntero, así que el propio borde es la señal.",
        "hotspotRevealed": "Toca cerca del borde derecho y la manija sale sola.",
        "keyboardIntro": "Tampoco necesitas un puntero.",
        "keyboardOutcome": "Presiona {{mod}} + K y se abre la misma ventana."
